import limited_client as robot
import numpy as np
from PIL import Image
s=robot.observe(camera=2)['robot']; q=np.array(s['joint_positions'],float)
print('before',s)
try: print('brake',robot.step(np.r_[q,[0.04,0.04]].tolist()))
except Exception as e: print('brake error',repr(e))
for cam in (1,2,3):
 o=robot.observe(camera=cam); Image.fromarray(o['rgb']).save(f'/app/output/inspect{cam}.png')
 print('\nCAM',cam,'robot',o['robot'],'T',o['camera_to_world'])
 if cam==1: pts={'bottle':(202,492),'shaker':(247,512),'packet':(278,525)}
 elif cam==2: pts={'bottle':(430,280),'nearby':(440,330)}
 else: pts={'food':(360,245),'dish':(380,235)}
 for name,(u,v) in pts.items():
  if not(0<=u<480 and 0<=v<480): continue
  d=o['depth_m']; K=o['intrinsic']; z=float(np.nanmedian(d[max(0,v-3):min(480,v+4),max(0,u-3):min(480,u+4)]))
  p=np.array([(u-K[0,2])*z/K[0,0],(v-K[1,2])*z/K[1,1],z,1.])
  print(name,(u,v),'depth',z,'world',(o['camera_to_world']@p)[:3])
print('STATUS',robot.status())
