q=np.array(s['joint_positions'],float)
try: print('close',robot.step(np.r_[q,[0.0,0.0]].tolist()))
except Exception as e: print('close error',repr(e))
for cam in (0,3): print('CAM',cam,robot.observe(camera=cam)['robot'])
